/* THE SYSTEM service worker: offline-first app shell.
 * - Everything the app needs is precached on install (the list and build hash are generated by tools/gen_precache.py).
 * - User data is NOT in these caches: it lives in IndexedDB, so updating the app never touches progress.
 * - A new version waits until the user taps "Update" in the app (no surprise reloads mid-quest).
 */
const BUILD = '1.0.0-cf7f5843c4'; /*BUILD*/
const CACHE = 'the-system-' + BUILD;
const PRECACHE = [/*PRECACHE_START*/
  './',
  './assets/branding/app-icon-192.png',
  './assets/branding/app-icon-512.png',
  './assets/branding/app-icon-maskable-192.png',
  './assets/branding/app-icon-maskable-512.png',
  './assets/branding/app-icon-maskable.svg',
  './assets/branding/app-icon.svg',
  './assets/branding/apple-touch-icon-180.png',
  './assets/branding/splash-mark.svg',
  './assets/branding/system-logo-1024.png',
  './assets/branding/system-logo.svg',
  './assets/favicon/favicon-16.png',
  './assets/favicon/favicon-32.png',
  './assets/favicon/favicon-48.png',
  './assets/favicon/favicon.ico',
  './assets/favicon/favicon.svg',
  './css/animations.css',
  './css/base.css',
  './css/components.css',
  './css/dashboard.css',
  './css/layout.css',
  './css/market.css',
  './css/quests.css',
  './css/tokens.css',
  './icons/icon-sprite.svg',
  './index.html',
  './js/app.js',
  './js/data/intelligence-bank.js',
  './js/data/market.js',
  './js/data/rewards.js',
  './js/data/romance-data.js',
  './js/data/titles.js',
  './js/engine/penalty-engine.js',
  './js/engine/progression-engine.js',
  './js/engine/reward-engine.js',
  './js/engine/title-engine.js',
  './js/engine/transaction-engine.js',
  './js/engine/xp-engine.js',
  './js/features/gallery.js',
  './js/features/inbox.js',
  './js/features/mini-games/checkers.js',
  './js/features/mini-games/chess.js',
  './js/features/mini-games/cube.js',
  './js/features/mini-games/sliding.js',
  './js/features/mini-games/sudoku.js',
  './js/features/mini-games/tictactoe.js',
  './js/quests/financial.js',
  './js/quests/intelligence.js',
  './js/quests/physique.js',
  './js/quests/romance.js',
  './js/state/event-bus.js',
  './js/state/migrations.js',
  './js/state/persistence.js',
  './js/state/store.js',
  './js/ui/dom.js',
  './js/ui/router.js',
  './js/utils/dates.js',
  './js/utils/formatting.js',
  './js/utils/ids.js',
  './js/utils/rng.js',
  './js/utils/validation.js',
  './js/views/arcade.js',
  './js/views/dashboard.js',
  './js/views/financial.js',
  './js/views/inbox.js',
  './js/views/intelligence.js',
  './js/views/market.js',
  './js/views/physique.js',
  './js/views/quests-list.js',
  './js/views/rewards.js',
  './js/views/romance.js',
  './js/views/settings.js',
  './js/views/shared.js',
  './js/views/summon.js',
  './manifest.webmanifest'
  /*PRECACHE_END*/];

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // 'reload' bypasses the HTTP cache so a new version never precaches stale files
    await Promise.all(PRECACHE.map((u) => cache.add(new Request(u, { cache: 'reload' }))));
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('the-system-') && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => { if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting(); });

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // Navigations always get the cached app shell (the app is a single page with hash routes).
    if (req.mode === 'navigate') {
      const shell = await cache.match('./index.html', { ignoreSearch: true });
      if (shell) return shell;
    }
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res && res.ok && res.type === 'basic') cache.put(req, res.clone());
      return res;
    } catch (e) {
      if (req.mode === 'navigate') { const shell = await cache.match('./index.html', { ignoreSearch: true }); if (shell) return shell; }
      return new Response('Offline and not cached.', { status: 503, headers: { 'Content-Type': 'text/plain' } });
    }
  })());
});
